## Approach

The rota problem is exactly a **maximum-flow** problem, so a greedy/backtracking search is neither needed nor safe — if the max flow equals the total number of places, a valid rota exists; if it falls short, **no** rota exists (flow is an exact certificate of infeasibility).

Network (all constraints map 1‑to‑1):

```
source ─cap=max_shifts→ engineer ─cap=1→ (engineer, day) ─cap=1→ ┬ shift.free  ─cap=headcount-min_seniors→ sink
                                                                └ shift.senior ─cap=min_seniors        → sink
```

* **`source → engineer` (cap = `max_shifts`)** = total workload limit.
* **`engineer → (engineer, day)` (cap = 1)** plus *all* shifts of that day funnelling through that single node = at most one shift per day (and, since a shift's places are all on one day, also guarantees **different** engineers per shift).
* **`(engineer, day) → shift.free` (cap = 1)** exists only if the shift id is in that engineer's `available`; **`→ shift.senior`** only for seniors and only when `min_seniors > 0`. Flow conservation caps the node's outflow at 1.
* **`shift.senior → sink` (cap = `min_seniors`) and `shift.free → sink` (cap = `headcount - min_seniors`)**. Since a shift can never receive more than `headcount`, forcing the *global* flow to `Σ headcount` forces every shift to be saturated **and** every senior bucket to be saturated at exactly `min_seniors` seniors.

A handful of cheap *necessary* conditions (day-wise place counts, senior availability, Σ `max_shifts`) are checked first; they can only reject genuinely impossible instances. Sizes are ~7k nodes / ~45k edges with a 4-hop diameter, which Dinic handles in well under a second.

```python
"""
On-call rota assignment: exact reduction to maximum flow (Dinic).

    source --cap=max_shifts--> engineer --cap=1--> (engineer, day)
                    |
                    +--cap=1--> shift.free   --cap=headcount-min_seniors--> sink
                    +--cap=1--> shift.senior --cap=min_seniors-----------> sink   (seniors only)

A flow of value sum(headcount) exists iff a valid rota exists:
  * engineer node capacity            -> max_shifts
  * (engineer, day) node capacity 1   -> one shift per day, distinct engineers per shift
  * edges only where shift in `available`
  * shift.senior bucket only reachable from seniors and forced to min_seniors
"""

from collections import deque


class _Dinic:
    """Dinic max-flow. An edge is [to, residual capacity, reverse-edge index]."""

    __slots__ = ("n", "g")

    def __init__(self, n: int) -> None:
        self.n = n
        self.g: list[list[list[int]]] = [[] for _ in range(n)]

    def add_edge(self, u: int, v: int, c: int) -> None:
        self.g[u].append([v, c, len(self.g[v])])
        self.g[v].append([u, 0, len(self.g[u]) - 1])

    def max_flow(self, s: int, t: int, limit: int) -> int:
        g, n = self.g, self.n
        level = [-1] * n
        it = [0] * n
        flow = 0

        def bfs() -> bool:
            for i in range(n):
                level[i] = -1
            level[s] = 0
            q = deque([s])
            while q:
                u = q.popleft()
                nl = level[u] + 1
                for to, cap, _rev in g[u]:
                    if cap and level[to] < 0:
                        level[to] = nl
                        q.append(to)
            return level[t] >= 0

        def dfs(u: int, f: int) -> int:
            if u == t:
                return f
            while it[u] < len(g[u]):
                e = g[u][it[u]]
                if e[1] and level[e[0]] == level[u] + 1:
                    d = dfs(e[0], e[1] if e[1] < f else f)
                    if d:
                        e[1] -= d
                        g[e[0]][e[2]][1] += d
                        return d
                it[u] += 1
            return 0

        while flow < limit and bfs():
            for i in range(n):
                it[i] = 0
            while flow < limit:
                d = dfs(s, limit - flow)
                if not d:
                    break
                flow += d
        return flow


def assign_shifts(shifts: list[tuple[str, int, int, int]],
                  engineers: dict[str, dict]) -> dict[str, list[str]] | None:
    n_shifts = len(shifts)
    shift_ids = [s[0] for s in shifts]
    days = [s[1] for s in shifts]
    heads = [s[2] for s in shifts]
    mins = [s[3] for s in shifts]
    total = sum(heads)

    # Nothing to fill: the empty rota is always valid.
    if total == 0:
        return {sid: [] for sid in shift_ids}

    names = list(engineers)
    n_eng = len(names)
    senior = [bool(engineers[nm]["senior"]) for nm in names]
    caps = [int(engineers[nm]["max_shifts"]) for nm in names]

    # ---- cheap necessary conditions (only ever reject impossible instances) ----
    if sum(caps) < total:
        return None

    pos = {sid: i for i, sid in enumerate(shift_ids)}
    eng_for_shift = [[] for _ in range(n_shifts)]
    for e, nm in enumerate(names):
        for sid in engineers[nm]["available"]:
            eng_for_shift[pos[sid]].append(e)

    for si in range(n_shifts):
        if len(eng_for_shift[si]) < heads[si]:
            return None
        if sum(1 for e in eng_for_shift[si] if senior[e]) < mins[si]:
            return None

    day_need, day_sen_need, day_engs = {}, {}, {}
    for si in range(n_shifts):
        d = days[si]
        day_need[d] = day_need.get(d, 0) + heads[si]
        day_sen_need[d] = day_sen_need.get(d, 0) + mins[si]
        day_engs.setdefault(d, set()).update(eng_for_shift[si])
    for d, pool in day_engs.items():
        if day_need[d] > len(pool):
            return None
        if day_sen_need[d] > sum(1 for e in pool if senior[e]):
            return None

    # ---- group each engineer's available shifts by day ----
    groups = []                                   # (engineer, day, [shift indices])
    for e in range(n_eng):
        if caps[e] <= 0:
            continue
        buckets: dict[int, list[int]] = {}
        for si in range(n_shifts):
            if e in eng_for_shift[si] and (heads[si] > mins[si] or (mins[si] > 0 and senior[e])):
                buckets.setdefault(days[si], []).append(si)
        for d, sis in buckets.items():
            groups.append((e, d, sis))

    # ---- build the network ----
    src = 0
    nxt = 1
    eng_node = list(range(nxt, nxt + n_eng)); nxt += n_eng
    ed_node: dict[tuple[int, int], int] = {}
    for e, d, _ in groups:
        ed_node[(e, d)] = nxt; nxt += 1
    sr_node = list(range(nxt, nxt + n_shifts)); nxt += n_shifts   # senior-only bucket
    fr_node = list(range(nxt, nxt + n_shifts)); nxt += n_shifts   # free bucket
    sink = nxt; nxt += 1

    dinic = _Dinic(nxt)
    for e in range(n_eng):
        if caps[e] > 0:
            dinic.add_edge(src, eng_node[e], caps[e])

    used = []                                     # (edge, engineer, shift) for read-back
    for e, d, sis in groups:
        node = ed_node[(e, d)]
        dinic.add_edge(eng_node[e], node, 1)
        for si in sis:
            if heads[si] > mins[si]:
                dinic.add_edge(node, fr_node[si], 1)
                used.append((dinic.g[node][-1], e, si))
            if mins[si] > 0 and senior[e]:
                dinic.add_edge(node, sr_node[si], 1)
                used.append((dinic.g[node][-1], e, si))

    for si in range(n_shifts):
        if mins[si] > 0:
            dinic.add_edge(sr_node[si], sink, mins[si])
        if heads[si] > mins[si]:
            dinic.add_edge(fr_node[si], sink, heads[si] - mins[si])

    if dinic.max_flow(src, sink, total) < total:
        return None                               # provably no valid rota

    out: dict[str, list[str]] = {sid: [] for sid in shift_ids}
    for edge, e, si in used:
        if edge[1] == 0:                          # residual capacity 0 -> edge carries flow
            out[shift_ids[si]].append(names[e])
    return out


if __name__ == "__main__":
    shifts = [("mon-day", 1, 2, 1), ("mon-night", 1, 1, 0), ("tue-day", 2, 1, 1)]
    engineers = {
        "ana": {"senior": True,  "max_shifts": 2, "available": {"mon-day", "mon-night", "tue-day"}},
        "raj": {"senior": False, "max_shifts": 1, "available": {"mon-day", "mon-night"}},
        "kim": {"senior": False, "max_shifts": 2, "available": {"mon-day"}},
    }
    print(assign_shifts(shifts, engineers))
    # {'mon-day': ['ana', 'kim'], 'mon-night': ['raj'], 'tue-day': ['ana']}

    print(assign_shifts(shifts, {**engineers, "raj": {"senior": False, "max_shifts": 0,
                                                       "available": {"mon-day", "mon-night"}}}))
    # None
```
